import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.wg_0zBou.js";const _=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"ops/troubleshooting.md","filePath":"ops/troubleshooting.md","lastUpdated":1795742187000}'),t={name:"ops/troubleshooting.md"};function l(r,e,i,n,s,p){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><h2 id="机器离线" tabindex="-1">机器离线 <a class="header-anchor" href="#机器离线" aria-label="Permalink to &quot;机器离线&quot;">​</a></h2><ol><li><code>mpctl status core</code> / <code>mpctl status agent</code> 确认服务在跑。</li><li>http 传输：core 访问 <code>http://&lt;agent&gt;:&lt;port&gt;/healthz</code>；确认 <code>MPANEL_AGENT_TOKEN</code> 与面板里填的一致。</li><li>reverse-ws：agent 日志里应有「已连接 core」；反向代理必须透传 <code>Upgrade</code>/<code>Connection</code> 头。</li><li>stdio：核心需显式设置 <code>MPANEL_ALLOW_STDIO=1</code>，且 <code>mpanel-agent</code> 在 PATH 或 <code>MPANEL_AGENT_ENTRY</code> 指向它。</li></ol><h2 id="站点-apply-失败" tabindex="-1">站点 apply 失败 <a class="header-anchor" href="#站点-apply-失败" aria-label="Permalink to &quot;站点 apply 失败&quot;">​</a></h2><ul><li>站点页会给出容器内 <code>caddy validate</code> 的输出尾部。常见原因：域名重复、上游不可达、root 不在 <code>MPANEL_SITES_ROOTS</code> 白名单、基础认证缺少 bcrypt 工具。</li><li>apply 失败会回滚到上一份 <code>Caddyfile</code>；<code>$MPANEL_AGENT_DATA_DIR/caddy/sites.d/&lt;id&gt;.caddy</code> 可手工检查。</li><li>Caddy 容器未部署时，站点全功能不可用，只能一键安装；安装后 <code>capabilities.caddy</code> 才会变为可用。</li><li>容器启动失败时到「编排」页查看 <code>mpanel-caddy</code> 日志，常见原因是 80/443 被占用或挂载路径无权访问。</li></ul><h2 id="一键初始化失败" tabindex="-1">一键初始化失败 <a class="header-anchor" href="#一键初始化失败" aria-label="Permalink to &quot;一键初始化失败&quot;">​</a></h2><ul><li>商店模板来自 GitHub：默认先试 raw，再回退 jsDelivr 与同源 <code>/store</code>，每个地址最多 10 秒。 全部不可达时在面板 <code>config.json</code> 设置 <code>storeUrl</code> 指向可达镜像。</li><li>安装需要 Docker Engine 与 Compose v2；错误输出会显示 <code>docker compose</code> 的原始信息。</li><li>数据库端口默认只绑定 <code>127.0.0.1</code>，端口冲突时修改安装向导中的宿主端口。</li></ul><h2 id="证书看不到" tabindex="-1">证书看不到 <a class="header-anchor" href="#证书看不到" aria-label="Permalink to &quot;证书看不到&quot;">​</a></h2><p>证书来自 Caddy 数据目录（<code>$MPANEL_AGENT_DATA_DIR/caddy/data</code> 或 <code>MPANEL_CADDY_DATA_DIR</code>）。 若 Caddy 尚未首次签发，列表为空属正常；签发后刷新页面即可。</p><h2 id="pty-不可用" tabindex="-1">PTY 不可用 <a class="header-anchor" href="#pty-不可用" aria-label="Permalink to &quot;PTY 不可用&quot;">​</a></h2><p>Windows 上 <code>creack/pty</code> 不可用，终端降级为管道模式（<code>pty=false</code>），交互式程序（vim/top）不可用。 Linux 上检查 agent 是否以能创建 <code>/dev/ptmx</code> 的用户运行。</p><h2 id="dbx-打不开" tabindex="-1">dbx 打不开 <a class="header-anchor" href="#dbx-打不开" aria-label="Permalink to &quot;dbx 打不开&quot;">​</a></h2><p>在面板部署目录的 <code>config.json</code> 设置 <code>dbxUrl</code>，或构建时设置 <code>VITE_DBX_URL</code>。 未配置时数据库页仍可用，只是不显示 iframe，可复制连接信息手工连接。</p><h2 id="边缘入网-403" tabindex="-1">边缘入网 403 <a class="header-anchor" href="#边缘入网-403" aria-label="Permalink to &quot;边缘入网 403&quot;">​</a></h2><p>密钥可能已吊销、过期或用尽（<code>maxUses</code>）。确认 <code>MPANEL_CORE_URL</code> 是 <strong>HTTP(S) 基地址</strong>， 不是 <code>ws://…/ws/worker</code>。审计日志中有 <code>edge.enroll</code> / <code>edge.job.*</code> 记录。</p><h2 id="端口-配置在哪" tabindex="-1">端口/配置在哪 <a class="header-anchor" href="#端口-配置在哪" aria-label="Permalink to &quot;端口/配置在哪&quot;">​</a></h2><p><code>/opt/mpanel/conf/app.yaml</code>（core）与 <code>/opt/mpanel/conf/agent.yaml</code>（agent）。 所有字段可用 <code>MPANEL_*</code> 环境变量覆盖，优先级：环境变量 &gt; 配置文件 &gt; 默认值。</p>',17)])])}const u=o(t,[["render",l]]);export{_ as __pageData,u as default};
